import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { loadReferenceIndex } from "../src/index.js";
import type { ReferenceAsset } from "../src/index.js";
import { syntheticFixture } from "./fixtures/synthetic.js";
import { runScenarios } from "./fixtures/parity/scenarios.js";
import type { ScenarioResult } from "./fixtures/parity/scenarios.js";
import { asset, tinyTilawa, wav } from "./helpers.js";

// Generated by scripts/parity-golden.mjs from the research session at the pinned commit.
const golden = JSON.parse(readFileSync(new URL("./fixtures/parity/golden.json", import.meta.url), "utf8")) as {
  commit: string;
  results: Record<string, ScenarioResult>;
};
const source = JSON.parse(readFileSync(new URL("../src/engine/SOURCE.json", import.meta.url), "utf8")) as { commit: string };
const plain = <T>(x: T): T => JSON.parse(JSON.stringify(x));
const V1_ONLY = ["sdkVersion", "modelSha256", "tier", "backend"];
const researchView = (e: unknown) =>
  (e as { type: string }).type === "capabilities"
    ? Object.fromEntries(Object.entries(e as object).filter(([k]) => !V1_ONLY.includes(k)))
    : e;

describe("parity with the research session", () => {
  it("was generated from the vendored commit", () => {
    expect(golden.commit).toBe(source.commit);
  });

  it("emits the same events, mistakes and evidence for the tiny model WAV and synthetic evidence", async () => {
    const tilawa = await tinyTilawa({ recordEvidence: true });
    const index = loadReferenceIndex(asset<ReferenceAsset>("ref-v2.json"));
    const results = await runScenarios({
      start: (p, policy) => (p ? tilawa.startMemorization(p, policy) : tilawa.startFreeRecitation(policy)) as never,
      wav: await wav(),
      index,
      synthetic: (spec) => syntheticFixture(index, spec as never).evidence,
    });
    expect(Object.keys(results)).toEqual(Object.keys(golden.results));
    for (const [name, want] of Object.entries(golden.results)) {
      const got = plain(results[name]);
      expect(got.returned, name).toEqual(want.returned);
      expect(got.subscribed.map(researchView), name).toEqual(want.subscribed);
      expect(got.mistakes, name).toEqual(want.mistakes);
      expect(got.evidence, name).toEqual(want.evidence);
    }
    // The scenarios exercise the checker, not just the tracker.
    expect(golden.results["evidence-wrong-word-free"].mistakes).toHaveLength(1);
    await tilawa.dispose();
  });
});
